INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (41, 52, 'BOPET TEAR TAPE (self-adhesive)', '../upload/image/20180923/20180923103926_16715.jpg', '<p></p><p style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">BOPET TEAR TAPE (self-adhesive)<br/> <br/> Item 01.<br/> Basic material : BOPET film ( polyester film) <br/> Thickness : 28-35 microns . <br/> Width :1.5-6.5MM (such as: 1.6,1.8,2.0,2.5,3.0,3.5,4.0,5.0,8.0MM)</span></span></span></p> <p style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">Length : 5000,6000,10000,18000M <br/> Color : red,white ,green,golden,black,yellowish,etc.<br/> Printing : can print any design-logoes ( private trade mark label) upon requirment.<br/> <br/> <br/> Item 02.<br/> Laser BOPP tear Tape (self adhesive) <br/> Basic material : Metallized BOPP (VMBOPP)<br/> Thickness : 28-35 microns . <br/> Width :1.5-6.5MM (such as: 1.6,1.8,2.0,2.5,3.0,3.5,4.0,5.0,8.0MM)</span></span></span></p> <p style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">Length : 5000,6000,10000,18000M <br/> Color : silver,golden ,laser etc.<br/> Printing : can print any design-logoes ( private trade mark label) upon requirment.<br/> <br/> <br/> Item 03.<br/> Metallized BOPET tear Tape(self adhesive) <br/> Basic material : Metallized BOPET (VMBOPET)<br/> Thickness : 75-150 microns . <br/> Width :1.5-2.0-3.5MM<br/> Length : 10000M <br/> Color : silver,golden ,laser etc.</span></span></span></p>', '2026-09-06 20:58:46');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (41, 53, 'BOPP CRYSTAL ADHESIVE TAPE JUMBO ROLLS', '../upload/image/20180923/20180923103958_85995.jpg', '<p><span style=''color:#3A3A3A;font-family:"font-size:16px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="font-family:Tahoma;"><span style="background-color:yellow;">BOPP Tape Jumbo Rolls<br/> BOPP CRYSTAL ADHESIVE TAPE JUMBO ROLLS</span></span></span></p><p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">BOPP crystal adhesive packing tape jumbo-rolls ( Bopp Transparent &amp; Brown Tapes acrylic water base size &amp; solvent &amp; rubber ) is widely used for slitting into medium/smaller rolls and for heavy-duty cartons sealing</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">.1) BOPP super clear adhesive packaging tape with water based acrylic adhesive, high-tensile strength and adhesion</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">2) Colors: Transparent/clear,tan,yellowish,red,dark brown,light tan,white,red,blue,green,black,multicolor and printed logo/letter so on.</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">3) Thickness: 35,36,38,39,40,41,42,45,48,50,53,55,58,60,63,65,68mic</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">4) Width: 520mm,980mm,1020mm,1265mm,1270mm,1280mm,1300mm,1620mm ,1640mm,and others</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">5) Length: 3000m,4000m,4500m,6000m</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">6.) Size:jumbo rolls tape</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"><span style="background-color:yellow;">6) Qty: 1200rolls/day</span></span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:20pt;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''></p> <span style=''color:#3A3A3A;font-family:"font-size:16px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="font-family:Tahoma;"> <p align="left" style="text-indent:20pt;"> <span style="background-color:yellow;">Customer''s own requirement is available for us. Such as : buyer''s own printed OEM logos,private label,particular size and private package styles.</span></p> </span></span><span style=''color:#3A3A3A;font-